// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-compress-gif' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>あなたのGIFは大きすぎて送れません。Discordが却下し、ページの読み込みが遅く、チャットアプリがアップロードを拒否します。</p>\n<p>GIFの圧縮は約2分で終わります。プリセットを選び、パレットとスケールを調整し、アニメーションをプレビューして、小さいファイルをダウンロードします。</p>\n<p>この記事では、ツールの起動から完成したGIFの現場での確認まで、すべての手順を順を追って説明します。</p>\n<h2 id=\"what-you-need\">始める前に必要なもの</h2>\n<p>元のGIFファイルが必要です。チャットアプリからダウンロードしたGIFはすでに圧縮されているかもしれないので、できれば元のファイルを使いましょう。</p>\n<p>達成しなければならないサイズ制限を知っておきます。Discord、Slack、Webサイトにはそれぞれ独自の上限があり、目標が設定を決めます。</p>\n<p>GIFがどこで表示されるかを知っておきます。小さく表示されるステッカーは、ブログ記事いっぱいに表示されるGIFより少ないデータしか必要としません。</p>\n<p>元画像は安全に保管します。別の設定で再挑戦する必要に備え、圧縮したコピーで上書きしないことです。</p>\n<h2 id=\"step-1-open\">ステップ1：GIF圧縮ツールを開く</h2>\n<p><a href=\"/ja/gif-asshuku/\">GIF圧縮ツール</a>をブラウザで開きます。アカウントもインストールも不要です。</p>\n<p>ツールはすべて端末内で動きます。アニメーションはローカルで処理され、サーバーにアップロードされることはありません。</p>\n<p>スマホでも同じように使えます。アップロードエリアをタップして、ファイルからGIFを選びましょう。</p>\n<p>GIFをよく圧縮するなら、このページをブックマークしましょう。リアクションGIFやクリップは、ほとんどの人にとって繰り返しのニーズです。</p>\n<h2 id=\"step-2-upload\">ステップ2：GIFをアップロードする</h2>\n<p>GIFをアップロードエリアにドラッグするか、タップして選択します。ツールはアニメーションを読み込み、フレーム、タイミング、ループ設定を含みます。</p>\n<p>GIFが完全に読み込まれるのを待ちます。大きなファイルは数秒かかり、ツールは作業の前にすべてのフレームを必要とします。</p>\n<p>ページに表示される元の詳細を確認します。変更する前に、ファイルサイズ、寸法、フレーム数をメモします。</p>\n<p>GIFが読み込まれない場合は、ファイルを確認します。壊れたダウンロードや、GIFではないのにGIFと名前を変えたファイルは、ここで失敗します。</p>\n<h2 id=\"step-3-preset\">ステップ3：プリセットを選ぶ</h2>\n<p>ほとんどのGIFにはバランスを選びます。パレットを減らし、フレームをいくらか間引き、賢くスケーリングして、よい中間点を与えます。</p>\n<p>GIFを美しく保たなければならない場合は「軽い」を選びます。パレットを穏やかに削り、アニメーションを滑らかに保ちます。</p>\n<p>厳しい制限に収めなければならない場合は「最大圧縮」を選びます。すべての手段を強く使い、最も小さいファイルを作ります。</p>\n<p>プリセットは出発点を決めます。プリセットを選んだ後、パレット、スケール、フレームレートを個別に調整できます。</p>\n<h2 id=\"step-4-adjust\">ステップ4：パレット・スケール・フレームを調整する</h2>\n<p>内容に合わせてカラーパレットを設定します。写真には128色か256色、平らな図形や漫画には64色か32色を使います。</p>\n<p>出力スケールは表示サイズに合わせます。400ピクセル幅で表示されるGIFは、ファイルで1000ピクセルである必要はありません。</p>\n<p>フレームレートは、GIFが長い場合にだけ調整します。フレームの間引きは、画面録画やゆっくりしたアニメーションで最も効果があります。</p>\n<p>設定は1回に1つだけ変えます。すべてを一度に変えると、どの調整が効いたのかわからなくなります。</p>\n<h2 id=\"step-5-run\">ステップ5：圧縮を実行する</h2>\n<p>圧縮を開始し、進捗を見守ります。ツールはフレームを処理し、小さいGIFを構築します。</p>\n<p>大きなGIFは小さなものより時間がかかります。20MBのクリップは、2MBのリアクションより処理時間が長くなります。</p>\n<p>ツールの実行中はタブを閉じないこと。作業はブラウザ内で行われるので、ページを閉じると圧縮が止まります。</p>\n<p>終わると、ツールに新しいファイルサイズと節約した割合が表示されます。一般的なGIFは半分以上小さくなります。</p>\n<h2 id=\"step-6-preview\">ステップ6：アニメーションをプレビューする</h2>\n<p>ダウンロード前に、圧縮したGIFをプレビューします。少なくとも1周は最後まで再生して見ましょう。</p>\n<p>まずタイミングを確認します。アニメーションは元画像と同じ速度で再生され、急いだり引きずったりしてはいけません。</p>\n<p>次に色を確認します。写真のGIFは小さなパレットで段差が出ることがありますが、図形はきれいなままであるべきです。</p>\n<p>最後に滑らかさを確認します。フレームを間引きすぎると、速い動きがぎこちなく見えますが、ゆっくりしたアニメーションは滑らかなままです。</p>\n<p>並べて表示できる場合は使いましょう。元画像と圧縮したコピーを一緒に見ると、劣化が見つけやすくなります。</p>\n<h2 id=\"step-7-download\">ステップ7：ダウンロードしてテストする</h2>\n<p>圧縮したGIFをダウンロードします。圧縮版であることが名前からわかります。</p>\n<p>端末でファイルサイズを確認します。使うプラットフォームの制限に収まっていることを確かめます。</p>\n<p>GIFが表示される場所でテストします。Discordで自分宛に送るか、表示されるページを開いて、再生を見ましょう。</p>\n<p>元ファイルは安全に保管します。圧縮したGIFに問題がある場合、探し回ることなく元ファイルから再挑戦できます。</p>\n<h2 id=\"fixing-problems\">よくある問題の修正</h2>\n<p>GIFがまだ収まらない場合は、スケールをさらに下げます。寸法を半分にすると、ファイルサイズは大幅に減ります。</p>\n<p>色がおかしく見える場合は、パレットを上げます。32色の写真のGIFはひどく段差が出ますが、128色にすれば修正できます。</p>\n<p>アニメーションがぎこちなく再生される場合は、間引いたフレームをいくらか戻します。速い動きは、滑らかに見えるために多くのフレームが必要です。</p>\n<p>ファイルが縮むどころか大きくなった場合、元画像はすでに非常に小さかったのです。無理に圧縮するのではなく、元ファイルをそのまま使いましょう。</p>\n<h2 id=\"discord-workflow\">作業例：Discord用のGIF</h2>\n<p>アカウントのDiscordの制限を確認します。無料アカウントはアップロードを8MBに制限し、目標が設定を決めます。</p>\n<p>GIFを圧縮ツールにアップロードし、制限を大きく超えている場合は「最大圧縮」を選びます。少し超えているだけなら、バランスで十分です。</p>\n<p>アニメーションを注意深くプレビューします。リアクションGIFは短いので、1周で劣化が簡単に見つかります。</p>\n<p>ファイルをダウンロードし、まず自分宛に送ります。サーバーで共有する前に、アップロードできて正しく再生されることを確認します。</p>\n<h2 id=\"website-workflow\">作業例：Webサイト用のGIF</h2>\n<p>ページでのGIFの役割を測ります。小さな装飾ループは、全幅のデモよりはるかに少ないデータしか必要としません。</p>\n<p>GIFをアップロードし、バランスを選びます。表示幅に合わせてスケーリングし、ファイルに無駄なピクセルを持たせません。</p>\n<p>表示されるサイズでアニメーションをプレビューします。大きく見て問題ないGIFも、小さく見ると粗く見えることがあり、その逆もあります。</p>\n<p>ファイルをダウンロードし、サイトにアップロードします。公開後、ページの読み込み時間を確認し、改善を確かめます。</p>\n<p>長いクリップには動画を検討します。10秒を超えるGIFはたいていMP4に属し、同じ内容でもはるかに小さいです。</p>\n<h2 id=\"phone-workflow\">作業例：スマホで行う</h2>\n<p>モバイルブラウザでツールを開き、アップロードエリアをタップします。ファイルからGIFを選びます。</p>\n<p>プリセットを選び、GIFが表示される場所に合わせてスケールを調整します。小さな画面には小さなファイルが必要です。</p>\n<p>スマホの画面でアニメーションをプレビューします。ダウンロード前に、1周を最後まで見ましょう。</p>\n<p>ファイルアプリでダウンロードしたファイルを見つけ、サイズを確認します。その後、Discord、Slack、または選んだチャットアプリに共有します。</p>\n<h2 id=\"gif-sizes-by-platform\">プラットフォームごとのサイズ制限</h2>\n<p>プラットフォームごとに、GIFアップロードの上限が違います。圧縮する前に上限を知っておけば、却下されるアップロードを防げます。</p>\n<p>Discordは無料アカウントで8MB、有料アカウントではさらに多く認めます。制限を少し超えたGIFは、わずかな削減で収まります。</p>\n<p>Slackはファイルのアップロードを1GBまで認めますが、数メガバイトを超えるGIFはチャットウィンドウでうまく再生されません。上限がゆるくても、小さいほうがよいです。</p>\n<p>Webサイトには固定の上限はありませんが、ページ速度は重いGIFに罰を与えます。ブログ記事の10MBのGIFは、すべての訪問者のページを遅くします。</p>\n<p>圧縮前に、プラットフォームの制限を確認します。目標がプリセットを決め、目標の推測は時間を無駄にします。</p>\n<h2 id=\"trimming-gifs\">圧縮前にGIFを切り取る</h2>\n<p>最も効果的な圧縮は、内容を取り除くことです。10秒から5秒に切り取ったGIFは、フレーム数が一瞬で半分になります。</p>\n<p>退屈な最初と最後を切り取ります。ほとんどのクリップには、1秒の導入と1秒の余韻があり、何も加えていません。</p>\n<p>最高のループポイントを保ちます。シームレスにループするGIFは、実際より長く感じられ、目に見える飛びのあるGIFは壊れて感じられます。</p>\n<p>圧縮する前に切り取り、後ではありません。圧縮ツールは、与えられたフレームで作業し、フレームが少なければ最初からファイルは小さくなります。</p>\n<p>GIFメーカーがアニメーションを作った場合は、そこでタイミングを調整します。圧縮時に間引くより、元でフレームを取り除くほうがきれいです。</p>\n<h2 id=\"preview-tips\">問題を見つけるプレビューのコツ</h2>\n<p>圧縮したGIFは、表示される端末でプレビューします。パソコンでは問題なく見えたGIFも、スマホでは粗く見えることがあります。</p>\n<p>少なくとも3周は最後まで見ましょう。ループポイントでのつまずきのような問題は、1回目の再生の後にだけ現れることがあります。</p>\n<p>暗い背景と明るい背景の両方でGIFを確認します。白では問題なく見えた透過の端が、暗い背景ではハローを見せることがあります。</p>\n<p>他の人に見てもらいましょう。新鮮な目が、数回のプレビュー後にあなたが気づかなくなったぎこちなさを見つけます。</p>\n<p>プレビューは、利用できる最も安い品質管理です。2分の視聴が、恥ずかしい共有を防ぎます。</p>\n<h2 id=\"gif-batch\">複数のGIFを一度に圧縮する</h2>\n<p>GIF圧縮ツールは、1回に1つのアニメーションを処理します。GIFのセットは、同じプリセットで1つずつ圧縮します。</p>\n<p>セット全体で設定を統一します。パレットやスケールが混ざったリアクションパックは、一緒に共有すると乱れて見えます。</p>\n<p>最初のGIFでうまくいった設定をメモします。残りに再利用すれば、毎回決め直すことなくセットが統一されます。</p>\n<p>静止画の一括処理には、<a href=\"/ja/matome-gazou-asshuku/\">複数画像一括圧縮ツール</a>を使います。写真はバッチで処理しますが、GIFは個別の対応が必要です。</p>\n<p>GIFのバッチ処理は、写真のバッチ処理より遅いですが、結果はよりよいです。各アニメーションには、独自のプレビューと独自の設定が必要です。</p>\n<h2 id=\"gif-quality-scale\">GIFの画質の判断：何を見るべきか</h2>\n<p>圧縮したGIFは、3つのことで判断します。滑らかさ、色、シャープさです。それぞれが独自の方法で失敗し、それぞれに独自の修正方法があります。</p>\n<p>滑らかさは、フレームを間引きすぎると失敗します。速い動きがぎこちなくなり、修正はフレームを戻すことです。</p>\n<p>色は、パレットが小さすぎると失敗します。肌に段差が出て、空に縞が出ます。修正は大きなパレットです。</p>\n<p>シャープさは、スケールが小さすぎると失敗します。細部がぼやけ、文字がやわらかくなり、修正は大きな出力スケールです。</p>\n<p>圧縮するたびに、3つすべてを確認します。3つすべてに合格したGIFは共有の準備ができており、1つでも失敗したものはもう一度実行が必要です。</p>\n<h2 id=\"when-gif-fails\">GIFが救えないとき</h2>\n<p>十分に圧縮できないGIFもあります。長くて細かい写真のクリップは、最大圧縮でも制限を超えたままになることがあります。</p>\n<p>その場合は、形式を変えましょう。MP4やアニメーションWebPに変換すれば、どんなGIFの設定よりもはるかに小さくなります。</p>\n<p>または、内容を変えます。クリップを切り取り、フレームを切り取り、フレームレートを下げることで、届かなかったGIFを届く範囲にできます。</p>\n<p>または、制限を受け入れます。GIFのままでなければならず、長くなければならないGIFは、有料アカウントのような高いアップロード上限が必要かもしれません。</p>\n<p>いつ止めるべきかを知ることも、技術の一部です。終わりのない圧縮の試みは、形式の変更が節約する時間を無駄にします。</p>\n<h2 id=\"gif-future\">Web上のGIFの未来</h2>\n<p>GIFは古いですが、消えていません。普遍的な再生が、チャット、メール、SNSでGIFを生かし続けています。</p>\n<p>Webサイトは、長いアニメーションを動画に移行しています。自動再生のMP4は、GIFのように振る舞いながら10分の1の重さで、その移行はすでに始まっています。</p>\n<p>アニメーションWebPは、中間地点として成長しています。よりよい圧縮で簡単な再生を保ち、ブラウザの対応は今や広いです。</p>\n<p>短いリアクションやステッカーでは、GIFは数年生き残ります。他の何ものも、ここまで普遍的に、ここまで少ない労力で再生できません。</p>\n<p>実用的な教訓は、仕事に適した形式を使うことです。普遍的な短いループにはGIF、効率的なWebアニメーションにはWebP、それより長いものにはMP4です。</p>\n<h2 id=\"keep-practising-gif\">実際のGIFで練習を続ける</h2>\n<p>圧縮するすべてのGIFが何かを教えます。どのプリセットが機能し、どのスケールが表示サイズに合い、ファイルサイズがどう動いたかをメモします。</p>\n<p>そのメモが、あなたのプレイブックになります。次のGIFは、前回のGIFがすでに質問に答えたので、短時間で終わります。</p>\n<p>GIF圧縮の詳しいガイドは、<a href=\"/ja/blog/gif-asshuku-kanzen-gaido/\">GIF圧縮の完全ガイド</a>をご覧ください。形式の比較は、<a href=\"/ja/blog/gif-vs-webp-vs-mp4-douga-hikaku/\">GIF・WebP・MP4の比較：アニメーション画像はどれがいい？</a>です。写真からGIFを作る場合は、<a href=\"/ja/gif-sakusei/\">GIFメーカー</a>が先に作ります。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Discord用にGIFを圧縮するにはどうしますか？","answer":"GIF圧縮ツールを開き、GIFをアップロードして、8MBの無料制限を大きく超えている場合は最大圧縮を選びます。表示サイズに合わせてスケールを下げ、アニメーションをプレビューします。ファイルをダウンロードして制限に収まることを確認し、まず自分宛に送って正しく再生されることを確かめます。"},{"question":"圧縮後にGIFがぎこちなく見えるのはなぜですか？","answer":"フレームを間引きすぎました。フレームの間引きは合計の長さを保ちますが、中間のフレームを取り除くので、速い動きがぎこちなく見えます。間引くフレームを減らすか、穏やかなプリセットで再挑戦し、ダウンロード前に1周を最後までプレビューしましょう。"},{"question":"GIFを画質を落とさずに圧縮できますか？","answer":"多少の損失は避けられません。GIFの圧縮は色、フレーム、ピクセルを取り除くからです。しかし、適切なパレットでバランスプリセットを使った注意深い圧縮は、損失をほぼ見えなく保ちます。すでに圧縮されたコピーではなく、元ファイルから始めましょう。"},{"question":"画面録画GIFに最適なパレットサイズは何ですか？","answer":"画面録画は平らな色とシャープな文字を使うので、64色がたいていうまく機能します。まず128色を試し、ファイルがまだ大きすぎる場合は64色に下げましょう。文字は両方のサイズで読めるままで、それが録画で重要なことです。"},{"question":"GIFはどれくらい小さくできますか？","answer":"長さ、寸法、内容によります。短いリアクションGIFは1MB以下になることもありますが、10秒のクリップは最大圧縮でも5MBを超えたままになることがあります。非常に長いクリップには、GIFよりMP4やWebP動画のほうが適した形式です。"},{"question":"GIFを圧縮すると透過は消えますか？","answer":"いいえ。圧縮中も透過は保持されます。透明な部分は、圧縮したファイルでも透明なままです。パレットの削減で、柔らかい透過の端が粗くなることがあるので、ステッカーや重ね合わせにはパレットを多めに保ちましょう。"}];
